mapper.select:
SELECT l.id as lease_id, l.tenant_id, l.company_id, l.dept_id, t.tenant_name AS tenant_name, t.tenant_phone as tenant_phone, lr.room_id, r.keywords as room_name, COALESCE(lr.rent_price, l.rent_price) as rent_price, l.deposit_months, l.payment_months, l.lease_start, l.lease_end, l.status, l.sign_status, l.check_out_status FROM lease l JOIN lease_room lr ON l.id = lr.lease_id LEFT JOIN room r ON lr.room_id = r.id JOIN tenant t ON l.tenant_id = t.id WHERE l.status IN
#{item}
AND lr.room_id = #{roomId} AND l.check_out_status = #{checkOutStatus} ORDER BY CASE WHEN l.status = 2 THEN 0 WHEN l.lease_start <= NOW() AND l.lease_end >= NOW() THEN 1 WHEN l.lease_start > NOW() THEN 2 ELSE 3 END, CASE WHEN l.lease_start > NOW() THEN TIMESTAMPDIFF(SECOND, NOW(), l.lease_start) WHEN l.lease_end < NOW() THEN TIMESTAMPDIFF(SECOND, l.lease_end, NOW()) ELSE 0 END, l.lease_start DESC, l.id DESC LIMIT 1

SELECT l.id as lease_id, l.tenant_id, l.company_id, l.dept_id, t.tenant_name AS tenant_name, t.tenant_phone as tenant_phone, lr.room_id, r.keywords as room_name, COALESCE(lr.rent_price, l.rent_price) as rent_price, l.deposit_months, l.payment_months, l.lease_start, l.lease_end, l.status, l.sign_status, l.check_out_status FROM lease l JOIN lease_room lr ON l.id = lr.lease_id LEFT JOIN room r ON lr.room_id = r.id JOIN tenant t ON l.tenant_id = t.id WHERE l.status IN
#{item}
AND l.check_out_status = #{checkOutStatus} AND lr.room_id IN
#{item}
ORDER BY lr.room_id, CASE l.status WHEN 2 THEN 0 WHEN 1 THEN 1 WHEN 0 THEN 2 ELSE 3 END, l.lease_start DESC, l.id DESC
